-500 mr-2', draft.collapsed ? 'fa-chevron-right' : 'fa-chevron-down']\" />\n          <span class=\"draft-name flex-1 truncate\">{{ draft.name || 'Untitled' }}</span>\n          <button class=\"del-btn\" title=\"删除\" @click.stop=\"store.removeDraft(draft.id)\">\n            <i class=\"fas fa-times text-xs\" />\n          </button>\n        </div>\n\n        <div v-if=\"!draft.collapsed\" class=\"draft-body\">\n          <input\n            class=\"draft-input\"\n            placeholder=\"条目名称\"\n            :value=\"draft.name\"\n            @input=\"store.updateDraft(draft.id, { name: ($event.target as HTMLInputElement).value })\"\n          />\n          <select\n            class=\"draft-select\"\n            :value=\"draft.role\"\n            @change=\"store.updateDraft(draft.id, { role: ($event.target as HTMLSelectElement).value as any })\"\n          >\n            <option value=\"system\">system</option>\n            <option value=\"user\">user</option>\n            <option value=\"assistant\">assistant</option>\n          </select>\n          <textarea\n            class=\"draft-textarea\"\n            placeholder=\"提示词内容...\"\n            :value=\"draft.content\"\n            rows=\"4\"\n            @input=\"store.updateDraft(draft.id, { content: ($event.target as HTMLTextAreaElement).value })\"\n          />\n        </div>\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useManagerStore, type DraftPrompt } from '../stores/manager';\n\nconst store = useManagerStore();\n\nconst drafts = computed(() => store.drafts);\n\nfunction toggleDraft(draft: DraftPrompt) {\n  store.updateDraft(draft.id, { collapsed: !draft.collapsed });\n}\n\nfunction onDragStart(e: DragEvent, draft: DraftPrompt) {\n  const prompt = store.draftToPrompt(draft);\n  e.dataTransfer!.effectAllowed = 'copy';\n  e.dataTransfer!.setData(\n    'application/json',\n    JSON.stringify({\n      type: 'draft',\n      source: 'workbench',\n      prompt,\n    }),\n  );\n}\n</script>\n\n<style scoped>\n.panel-title {\n  min-height: 42px;\n  border-bottom: 1px solid var(--pm-border);\n  padding-right: 40px;\n}\n.add-btn {\n  width: 26px;\n  height: 26px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  border-radius: 999px;\n  border: 1px solid var(--pm-border);\n  background: transparent;\n  color: var(--pm-text-muted);\n  cursor: pointer;\n  transition: all 0.12s;\n}\n.add-btn:hover {\n  background: var(--pm-accent);\n  color: var(--pm-accent-text);\n  border-color: var(--pm-accent);\n}\n.draft-item {\n  border: 1px solid transparent;\n  border-radius: 8px;\n  background: transparent;\n  margin-bottom: 3px;\n  cursor: grab;\n}\n.draft-item:hover {\n  border-color: var(--pm-border);\n  background: var(--pm-bg-hover);\n}\n.draft-header {\n  display: flex;\n  align-items: center;\n  min-height: 34px;\n  padding: 6px 8px;\n  cursor: pointer;\n}\n.draft-name {\n  font-size: 12px;\n  color: var(--pm-text);\n}\n.del-btn {\n  width: 20px;\n  height: 20px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  border-radius: 4px;\n  border: none;\n  background: transparent;\n  color: var(--pm-text-subtle);\n  cursor: pointer;\n}\n.del-btn:hover {\n  color: var(--pm-danger);\n  background: color-mix(in srgb, var(--pm-danger) 13%, transparent);\n}\n.draft-body {\n  padding: 6px 8px 8px;\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n  border-top: 1px solid var(--pm-border);\n}\n.draft-input,\n.draft-select {\n  width: 100%;\n  padding: 6px 9px;\n  border-radius: 8px;\n  border: 1px solid var(--pm-border);\n  background: var(--pm-input-bg);\n  color: var(--pm-text);\n  font-size: 12px;\n  outline: none;\n}\n.draft-input:focus,\n.draft-select:focus {\n  border-color: var(--pm-border-strong);\n}\n.draft-select option {\n  background: var(--pm-bg-elevated);\n}\n.draft-textarea {\n  width: 100%;\n  padding: 8px 9px;\n  border-radius: 8px;\n  border: 1px solid var(--pm-border);\n  background: var(--pm-input-bg);\n  color: var(--pm-text);\n  font-size: 12px;\n  resize: vertical;\n  min-height: 60px;\n  outline: none;\n  font-family: inherit;\n}\n.draft-textarea:focus {\n  border-color: var(--pm-border-strong);\n}\n</style>\n"],"sourceRoot":""}]);
