/>\n            </button>\n          </div>\n\n          <div class=\"panel-body\">\n            <div class=\"section\">\n              <div class=\"section-title flex items-center justify-between\">\n                <span>操作记录</span>\n                <span class=\"text-xs text-slate-500\">{{ history.undoStack.length }} / 50</span>\n              </div>\n              <div v-if=\"!history.undoStack.length\" class=\"text-xs text-slate-600 py-2\">无操作记录</div>\n              <div v-for=\"(record, i) in [...history.undoStack].reverse().slice(0, 10)\" :key=\"i\" class=\"record-item\">\n                <span class=\"record-desc\">{{ record.description }}</span>\n                <span class=\"record-time\">{{ formatTime(record.timestamp) }}</span>\n              </div>\n            </div>\n\n            <div class=\"section\">\n              <div class=\"section-title flex items-center justify-between\">\n                <span>快照备份</span>\n                <button class=\"snapshot-btn\" @click=\"createManualSnapshot\">\n                  <i class=\"fas fa-camera mr-1\" /> 创建快照\n                </button>\n              </div>\n              <div v-if=\"!history.snapshots.length\" class=\"text-xs text-slate-600 py-2\">无备份快照</div>\n              <div v-for=\"snap in history.snapshots\" :key=\"snap.id\" class=\"snapshot-item\">\n                <div class=\"snap-info\">\n                  <span class=\"snap-name\">{{ snap.name }}</span>\n                  <span class=\"snap-meta\">\n                    {{ snap.presetName }} · {{ formatTime(snap.timestamp) }}\n                    <span v-if=\"snap.auto\" class=\"auto-badge\">自动</span>\n                  </span>\n                </div>\n                <div class=\"snap-actions\">\n                  <button class=\"snap-btn\" title=\"回档\" @click=\"restore(snap.id)\">\n                    <i class=\"fas fa-undo text-xs\" />\n                  </button>\n                  <button class=\"snap-btn\" title=\"删除\" @click=\"history.deleteSnapshot(snap.id)\">\n                    <i class=\"fas fa-trash text-xs\" />\n                  </button>\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </div>\n    </Transition>\n  </Teleport>\n</template>\n\n<script setup lang=\"ts\">\nimport { useHistoryStore } from '../stores/history';\nimport { useManagerStore } from '../stores/manager';\n\ndefineProps<{ visible: boolean }>();\ndefineEmits<{ close: [] }>();\n\nconst history = useHistoryStore();\nconst manager = useManagerStore();\n\nfunction formatTime(ts: number) {\n  const d = new Date(ts);\n  return `${d.getHours().toString().padStart(2, '0')}:${d.getMinutes().toString().padStart(2, '0')}`;\n}\n\nfunction createManualSnapshot() {\n  const name = manager.presetName;\n  if (!name) {\n    toastr.warning('请先选择预设', '', { timeOut: 2000 });\n    return;\n  }\n  const snap = history.createSnapshot(name, `手动备份 - ${name}`);\n  if (snap) toastr.success('快照已创建', '', { timeOut: 1500 });\n}\n\nasync function restore(id: string) {\n  if (!confirm('确定回档到此快照？当前更改将被覆盖（可通过撤回恢复）。')) return;\n  const ok = await history.restoreSnapshot(id);\n  if (ok) {\n    manager.refreshMainPreset();\n    manager.refreshSecondPreset();\n    toastr.success('回档成功', '', { timeOut: 1500 });\n  } else {\n    toastr.error('回档失败', '', { timeOut: 2000 });\n  }\n}\n</script>\n\n<style scoped>\n.history-overlay {\n  position: fixed;\n  inset: 0;\n  background: color-mix(in srgb, var(--pm-bg) 65%, rgba(0, 0, 0, 0.35));\n  z-index: 900;\n  display: flex;\n  justify-content: flex-end;\n  backdrop-filter: blur(8px);\n}\n.history-panel {\n  width: 360px;\n  max-width: 90%;\n  background: var(--pm-bg-panel);\n  border-left: 1px solid var(--pm-border-strong);\n  display: flex;\n  flex-direction: column;\n  overflow: hidden;\n  box-shadow: var(--pm-shadow);\n}\n.panel-header {\n  border-bottom: 1px solid var(--pm-border);\n}\n.close-btn {\n  width: 28px;\n  height: 28px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  border-radius: 999px;\n  border: 1px solid transparent;\n  background: transparent;\n  color: var(--pm-text-muted);\n  cursor: pointer;\n}\n.close-btn:hover {\n  background: var(--pm-bg-hover);\n  color: var(--pm-text);\n  border-color: var(--pm-border);\n}\n.panel-body {\n  flex: 1;\n  overflow-y: auto;\n  padding: 12px;\n}\n.section {\n  margin-bottom: 16px;\n}\n.section-title {\n  font-size: 12px;\n  font-weight: 600;\n  color: var(--pm-text-muted);\n  margin-bottom: 8px;\n  text-transform: uppercase;\n  letter-spacing: 0.05em;\n}\n.record-item {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  padding: 4px 8px;\n  border-radius: 4px;\n  margin-bottom: 2px;\n}\n.record-item:hover {\n  background: var(--pm-bg-hover);\n}\n.record-desc {\n  font-size: 11px;\n  color: var(--pm-text);\n}\n.record-time {\n  font-size: 10px;\n  color: var(--pm-text-subtle);\n}\n.snapshot-btn {\n  padding: 5px 10px;\n  border-radius: 999px;\n  border: 1px solid var(--pm-border);\n  background: transparent;\n  color: var(--pm-text);\n  font-size: 11px;\n  cursor: pointer;\n  transition: all 0.12s;\n}\n.snapshot-btn:hover {\n  background: var(--pm-bg-hover);\n}\n.snapshot-item {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 8px;\n  border: 1px solid var(--pm-border);\n  border-radius: 8px;\n  margin-bottom: 4px;\n}\n.snapshot-item:hover {\n  border-color: var(--pm-border-strong);\n}\n.snap-info {\n  display: flex;\n  flex-direction: column;\n  min-width: 0;\n}\n.snap-name {\n  font-size: 12px;\n  color: var(--pm-text);\n  word-break: break-all;\n}\n.snap-meta {\n  font-size: 10px;\n  color: var(--pm-text-subtle);\n  margin-top: 2px;\n}\n.auto-badge {\n  padding: 0 4px;\n  border-radius: 999px;\n  background: var(--pm-bg-elevated);\n  color: var(--pm-text-muted);\n  font-size: 9px;\n  margin-left: 4px;\n}\n.snap-actions {\n  display: flex;\n  gap: 4px;\n  flex-shrink: 0;\n}\n.snap-btn {\n  width: 24px;\n  height: 24px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  border-radius: 999px;\n  border: 1px solid transparent;\n  background: transparent;\n  color: var(--pm-text-subtle);\n  cursor: pointer;\n}\n.snap-btn:hover {\n  color: var(--pm-text);\n  background: var(--pm-bg-hover);\n  border-color: var(--pm-border);\n}\n.slide-enter-active, .slide-leave-active {\n  transition: all 0.2s ease;\n}\n.slide-enter-from, .slide-leave-to {\n  opacity: 0;\n}\n.slide-enter-from .history-panel, .slide-leave-to .history-panel {\n  transform: translateX(100%);\n}\n</style>\n"],"sourceRoot":""}]);
